  if($a==='cash_move'){$c=open_cash();if(!$c)throw new RuntimeException('Abra o caixa.');$type=$_POST['tipo']==='sangria'?'sangria':'suprimento';$val=abs(decimal($_POST['valor']));$pdo->prepare("INSERT INTO caixa_movimentos(caixa_id,tipo,forma,valor,descricao,usuario_id) VALUES(?,?,'dinheiro',?,?,?)")->execute([$c['id'],$type,$val,trim($_POST['descricao']),$_SESSION['user']['id']]);flash('success','Movimento registrado.');redirect('?page=caixa');}
