   $pdo->beginTransaction();foreach($cart as $i){$s=$pdo->prepare('SELECT estoque_atual FROM produto_variacoes WHERE id=? FOR UPDATE');$s->execute([$i['id']]);if((float)$s->fetchColumn()<$i['qty'])throw new RuntimeException('Estoque insuficiente para '.$i['desc']);}
   $number='V'.date('YmdHis').random_int(10,99);$s=$pdo->prepare('INSERT INTO vendas(numero,cliente_id,caixa_id,usuario_id,subtotal,desconto,total) VALUES(?,?,?,?,?,?,?)');$s->execute([$number,$client,$c['id'],$_SESSION['user']['id'],$subtotal,$discount,$total]);$sale=(int)$pdo->lastInsertId();$ratio=$subtotal>0?$discount/$subtotal:0;
   foreach($cart as $i){$itotal=$i['price']*$i['qty']*(1-$ratio);$pdo->prepare('INSERT INTO venda_itens(venda_id,variacao_id,descricao,quantidade,preco_unitario,custo_unitario,desconto,total) VALUES(?,?,?,?,?,?,?,?)')->execute([$sale,$i['id'],$i['desc'],$i['qty'],$i['price'],$i['cost'],$i['price']*$i['qty']*$ratio,$itotal]);$old=$i['stock'];$new=$old-$i['qty'];$pdo->prepare('UPDATE produto_variacoes SET estoque_atual=estoque_atual-? WHERE id=?')->execute([$i['qty'],$i['id']]);$pdo->prepare("INSERT INTO estoque_movimentos(variacao_id,tipo,quantidade,saldo_anterior,saldo_posterior,custo_unitario,referencia_tipo,referencia_id,usuario_id) VALUES(?,'venda',?,?,?,?, 'venda',?,?)")->execute([$i['id'],-$i['qty'],$old,$new,$i['cost'],$sale,$_SESSION['user']['id']]);}
   $parts=$form==='crediario'?max(1,(int)$_POST['parcelas']):1;$pdo->prepare('INSERT INTO venda_pagamentos(venda_id,forma,valor,parcelas) VALUES(?,?,?,?)')->execute([$sale,$form,$total,$parts]);
