   else{$pdo->prepare('INSERT INTO caixa_movimentos(caixa_id,tipo,forma,valor,referencia_tipo,referencia_id,usuario_id) VALUES(?,"venda",?,?,"venda",?,?)')->execute([$c['id'],$form,$total,$sale,$_SESSION['user']['id']]);}
