function titlebar(string $title,string $sub=''):void{echo '<div class="section-title"><div><h1>'.e($title).'</h1><span class="muted">'.e($sub).'</span></div></div>';}
if($page==='dashboard'){
 $m=[];foreach(['today'=>"SELECT COALESCE(SUM(total),0) FROM vendas WHERE status='finalizada' AND DATE(criado_em)=CURDATE()", 'month'=>"SELECT COALESCE(SUM(total),0) FROM vendas WHERE status='finalizada' AND YEAR(criado_em)=YEAR(CURDATE()) AND MONTH(criado_em)=MONTH(CURDATE())",'low'=>"SELECT COUNT(*) FROM produto_variacoes WHERE ativo=1 AND estoque_atual<=estoque_minimo",'late'=>"SELECT COALESCE(SUM(valor_original-valor_pago),0) FROM crediario_parcelas WHERE status IN('aberta','parcial') AND vencimento<CURDATE()"] as $k=>$q)$m[$k]=$pdo->query($q)->fetchColumn();titlebar('Visão geral','Resumo da operação');echo '<div class="grid cards">';foreach([['Vendas hoje',money($m['today'])],['Vendas no mês',money($m['month'])],['Estoque baixo',$m['low']],['Crediário vencido',money($m['late'])]] as $x)echo "<div class=card><h3>{$x[0]}</h3><div class=metric>{$x[1]}</div></div>";echo '</div>';
}elseif($page==='estoque'){
 titlebar('Estoque','Consulte saldos e faça ajustes rápidos');
 $sum=$pdo->query("SELECT COUNT(*) variacoes,COALESCE(SUM(estoque_atual),0) unidades,COALESCE(SUM(estoque_atual*preco_custo),0) valor_custo,SUM(estoque_atual<=0) zerados,SUM(estoque_atual>0 AND estoque_atual<=estoque_minimo) baixos FROM produto_variacoes WHERE ativo=1")->fetch();
 $q=trim($_GET['q']??'');$status=$_GET['status']??'todos';$where=" WHERE pv.ativo=1 AND p.ativo=1";$params=[];
 if($q!==''){$where.=" AND (p.nome LIKE ? OR pv.sku LIKE ? OR pv.codigo_barras LIKE ? OR c.nome LIKE ? OR t.nome LIKE ?)";$like='%'.$q.'%';$params=array_fill(0,5,$like);}
 if($status==='zerado')$where.=" AND pv.estoque_atual<=0";elseif($status==='baixo')$where.=" AND pv.estoque_atual>0 AND pv.estoque_atual<=pv.estoque_minimo";elseif($status==='normal')$where.=" AND pv.estoque_atual>pv.estoque_minimo";
 $s=$pdo->prepare("SELECT pv.id,p.nome,pv.sku,pv.codigo_barras,c.nome cor,t.nome tamanho,pv.estoque_atual,pv.estoque_minimo,pv.preco_custo,pv.preco_venda,pv.localizacao FROM produto_variacoes pv JOIN produtos p ON p.id=pv.produto_id LEFT JOIN cores c ON c.id=pv.cor_id LEFT JOIN tamanhos t ON t.id=pv.tamanho_id".$where." ORDER BY (pv.estoque_atual<=0) DESC,(pv.estoque_atual<=pv.estoque_minimo) DESC,p.nome,c.nome,t.ordem LIMIT 500");$s->execute($params);$vars=$s->fetchAll();?>
