<?php }elseif($page==='clientes'){titlebar('Clientes','Cadastro e limite do crediário');?><div class="card"><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="customer_save"><div class="form-grid"><div><label>Nome</label><input name="nome" required></div><div><label>CPF</label><input name="cpf"></div><div><label>Telefone</label><input name="telefone"></div><div><label>E-mail</label><input name="email"></div><div><label>Limite de crédito</label><input name="limite_credito" value="0,00"></div><div><label>Endereço</label><input name="endereco"></div></div><label>Observações</label><textarea name="observacoes"></textarea><p><button class="btn primary">Cadastrar</button></p></form></div><br><?php $rows=$pdo->query("SELECT c.*,COALESCE(SUM(CASE WHEN cp.status IN('aberta','parcial') THEN cp.valor_original-cp.valor_pago ELSE 0 END),0) usado FROM clientes c LEFT JOIN crediario_parcelas cp ON cp.cliente_id=c.id GROUP BY c.id ORDER BY c.nome")->fetchAll();?><div class="table-wrap"><table><tr><th>Cliente</th><th>CPF</th><th>Telefone</th><th>Limite</th><th>Utilizado</th><th>Disponível</th></tr><?php foreach($rows as $r):?><tr><td><?=e($r['nome'])?></td><td><?=e($r['cpf'])?></td><td><?=e($r['telefone'])?></td><td><?=money($r['limite_credito'])?></td><td><?=money($r['usado'])?></td><td><?=money($r['limite_credito']-$r['usado'])?></td></tr><?php endforeach?></table></div>
