?=e(app_setting('max_parcelas',6))?>" value="1"><label>Primeiro vencimento</label><input type="date" name="primeiro_vencimento" value="<?=date('Y-m-d',strtotime('+30 days'))?>"></div><p><button class="btn primary block">Finalizar venda</button></p></form><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cart_clear"><button class="btn ghost block">Limpar</button></form></aside></div>
<?php }elseif($page==='caixa'){titlebar('Caixa','Abertura, sangria, suprimento e fechamento');$c=open_cash();if(!$c):?><div class="card"><h2>Caixa fechado</h2><form method="post"><?=csrf_field()?><input type="hidden" name="action" value="cash_open"><label>Valor inicial</label><input name="valor" value="0,00"><p><button class="btn primary">Abrir caixa</button></p></form></div><?php else:$s=$pdo->prepare("SELECT forma,SUM(CASE WHEN tipo IN('venda','recebimento','suprimento') THEN valor ELSE -valor END) total FROM caixa_movimentos WHERE caixa_id=? GROUP BY forma");$s->execute([$c['id']]);?><div class="grid cards"><div class="card"><h3>Abertura</h3><div class="metric"><?=money($c['valor_abertura'])?></div></div><?php foreach($s as $x):?><div class="card"><h3><?=e(ucfirst($x['forma']))?></h3><div class="metric"><?=money($x['total'])?></div></div><?php endforeach?></div><br><div class="card"><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="action" value="cash_move"><div><label>Tipo</label><select name="tipo"><option>suprimento</option><option>sangria</option></select></div><div><label>Valor</label><input name="valor" required></div><div class="grow"><label>Descrição</label><input name="descricao" required></div><button class="btn primary">Registrar</button></form><hr><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="action" value="cash_close"><div><label>Dinheiro contado</label><input name="valor" required></div><div class="grow"><label>Observação</label><input name="observacao"></div><button class="btn danger" data-confirm="Fechar o caixa?">Fechar caixa</button></form></div><?php endif;
}elseif($page==='crediario'){titlebar('Crediário','Parcelas simples e recebimentos');$rows=$pdo->query("SELECT cp.*,c.nome,v.numero,(cp.valor_original-cp.valor_pago) saldo FROM crediario_parcelas cp JOIN clientes c ON c.id=cp.cliente_id JOIN vendas v ON v.id=cp.venda_id WHERE cp.status IN('aberta','parcial') ORDER BY cp.vencimento")->fetchAll();?><div class="table-wrap"><table><tr><th>Vencimento</th><th>Cliente</th><th>Venda/parcela</th><th>Original</th><th>Saldo</th><th>Receber</th></tr><?php foreach($rows as $r):?><tr><td><span class="badge <?=$r['vencimento']<date('Y-m-d')?'danger':''?>"><?=e(date('d/m/Y',strtotime($r['vencimento'])))?></span></td><td><?=e($r['nome'])?></td><td><?=e($r['numero'].' / '.$r['numero_parcela'])?></td><td><?=money($r['valor_original'])?></td><td><?=money($r['saldo'])?></td><td><form method="post" class="row"><?=csrf_field()?><input type="hidden" name="action" value="credit_receive"><input type="hidden" name="parcela_id" value="<?=$r['id']?>"><input name="valor" value="<?=number_format($r['saldo'],2,',','.')?>" style="width:100px"><select name="forma" style="width:110px"><option>dinheiro</option><option>pix</option><option>debito</option><option>credito</option></select><button class="btn primary">Receber</button></form></td></tr><?php endforeach?></table></div>
